package ru.livingvillages;

import org.junit.jupiter.api.*;
import ru.livingvillages.domain.*;
import ru.livingvillages.persistence.Database;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class DomainTest {
    Rules rules;
    @BeforeEach void setup(){
        rules=new Rules();rules.foods.put("CARROT",2);rules.foods.put("BREAD",4);
        rules.prices.put("CARROT",new Rules.Price(3,160,4,90));rules.prices.put("COBBLESTONE",new Rules.Price(1,192,8,30));
        rules.prices.put("WHEAT",new Rules.Price(1,128,8,30));rules.prices.put("BREAD",new Rules.Price(6,80,4,120));
        rules.recipes.put("garden",new Rules.Recipe("FARMER",Map.of(),Map.of("CARROT",24),"irrigated",1,1));
        rules.recipes.put("bread",new Rules.Recipe("ARTISAN",Map.of("WHEAT",12),Map.of("BREAD",4),"land",1,1));
    }
    Village village(int residents){Village v=new Village();v.world=UUID.randomUUID();v.culture="polevichi";v.name="Тест";v.laws.immigration=false;v.laws.strategic.clear();for(int i=0;i<residents;i++){var r=new Village.Resident();r.name="Житель "+i;r.role=i==0?Village.Role.ELDER:Village.Role.FARMER;v.residents.add(r);}return v;}
    @Test void coinSplitConservesValue(){Random random=new Random(58);for(int i=0;i<100000;i++){long n=random.nextLong(100_000_000);long sum=Money.split(n).entrySet().stream().mapToLong(e->(long)e.getKey()*e.getValue()).sum();assertEquals(n,sum);}}
    @Test void moneyRejectsOverflowAndInvalidAmounts(){assertThrows(IllegalArgumentException.class,()->Money.checked(-1));assertThrows(IllegalArgumentException.class,()->Money.checked(Long.MAX_VALUE));assertThrows(IllegalArgumentException.class,()->Money.add(Money.MAX,1));assertThrows(IllegalArgumentException.class,()->Money.cost(5,0));assertThrows(IllegalArgumentException.class,()->Money.cost(Money.MAX,4096));}
    @Test void reservationIsAtomicAndCannotBeSpentTwice(){Stock s=new Stock();s.add("STONE",10,64);assertThrows(IllegalArgumentException.class,()->s.reserve(Map.of("STONE",4,"WOOD",1)));assertEquals(10,s.get("STONE"));Map<String,Integer> escrow=s.reserve(Map.of("STONE",8));assertEquals(8,escrow.get("STONE"));assertEquals(2,s.get("STONE"));assertThrows(IllegalArgumentException.class,()->s.reserve(Map.of("STONE",8)));}
    @Test void capacityAndNegativeStockAreRejected(){Stock s=new Stock();s.add("STONE",64,64);assertThrows(IllegalArgumentException.class,()->s.add("WOOD",1,64));assertThrows(IllegalArgumentException.class,()->s.take("STONE",65));assertThrows(IllegalArgumentException.class,()->s.add("STONE",-1,64));}
    @Test void lastBatchCannotBeSoldTwice(){Village v=village(5);v.stock.add("COBBLESTONE",8,v.capacity);Economy e=new Economy(rules);UUID a=UUID.randomUUID(),b=UUID.randomUUID();var qa=e.quote(v,a,"COBBLESTONE",8,true);var qb=e.quote(v,b,"COBBLESTONE",8,true);long original=v.treasury;e.trade(v,a,qa);assertThrows(IllegalArgumentException.class,()->e.trade(v,b,qb));assertEquals(0,v.stock.get("COBBLESTONE"));assertEquals(original+qa.total(),v.treasury);}
    @Test void treasuryDoesNotRegenerateAndCannotOverpay(){Village v=village(5);v.treasury=1;Economy e=new Economy(rules);var q=e.quote(v,UUID.randomUUID(),"CARROT",4,false);assertThrows(IllegalArgumentException.class,()->e.trade(v,UUID.randomUUID(),q));assertEquals(1,v.treasury);new Simulation(rules).day(v);assertEquals(1,v.treasury);assertEquals(1,Database.copy(v).treasury);}
    @Test void foodExportRespectsLawAndReserve(){Village v=village(5);v.stock.add("CARROT",25,v.capacity);Economy e=new Economy(rules);assertEquals(0,e.exportable(v,"CARROT"));v.laws.exportFood=true;assertEquals(5,e.exportable(v,"CARROT"));v.stock.take("CARROT",10);assertEquals(0,e.exportable(v,"CARROT"));}
    @Test void foodDemandSubtractsExistingNutritionOnlyOnce(){Village v=village(5);v.stock.add("CARROT",10,v.capacity);assertEquals(60,new Economy(rules).needed(v,"CARROT"));v.stock.add("CARROT",60,v.capacity);assertEquals(0,new Economy(rules).needed(v,"CARROT"));}
    @Test void usefulTradeHasDailyDiminishingTrust(){Village v=village(1);TestDemand.add(v,"COBBLESTONE",160);Economy e=new Economy(rules);UUID p=UUID.randomUUID();v.capacity=10000;v.treasury=100000;for(int i=0;i<20;i++){v.stock.items.clear();var q=e.quote(v,p,"COBBLESTONE",8,false);e.trade(v,p,q);}assertEquals(1,v.relation(p).trust);assertEquals(1,v.relation(p).tradeToday);}
    @Test void sustainedHungerKillsEveryoneGradually(){Village v=village(5);Simulation s=new Simulation(rules);s.day(v);assertEquals(5,v.living());s.day(v);assertEquals(5,v.living());s.day(v);assertEquals(4,v.living());for(int i=0;i<6;i++)s.day(v);assertEquals(0,v.living());assertTrue(v.abandoned);}
    @Test void oneFoodDoesNotResetWholeVillageStarvation(){Village v=village(5);Simulation s=new Simulation(rules);s.day(v);s.day(v);v.stock.add("CARROT",1,v.capacity);s.day(v);assertEquals(.1,v.nutrition,.0001);assertTrue(v.residents.stream().allMatch(r->r.hungerDays>2.8));}
    @Test void sufficientFoodAllowsRecovery(){Village v=village(2);Simulation s=new Simulation(rules);s.day(v);s.day(v);v.stock.add("BREAD",8,v.capacity);s.day(v);s.day(v);assertEquals(2,v.living());assertTrue(v.residents.stream().allMatch(r->r.hungerDays==0));}
    @Test void excessNutritionIsNotLost(){Village v=village(1);rules.foodPerResident=3;v.stock.add("BREAD",3,v.capacity);Simulation s=new Simulation(rules);for(int i=0;i<4;i++)s.day(v);assertEquals(1,v.nutrition);assertEquals(0,v.stock.get("BREAD"));assertEquals(0,v.nutritionCarry);}
    @Test void onlyCompletedConfirmedWorkplaceWithWorkerProduces(){Village v=village(1);v.stock.add("STONE_HOE",1,v.capacity);var b=new Village.Building();b.recipe="garden";v.buildings.add(b);Simulation s=new Simulation(rules);s.day(v);assertEquals(0,v.stock.get("CARROT"));b.complete=true;b.resourceConfirmed=true;s.day(v);assertEquals(0,v.stock.get("CARROT"));v.residents.getFirst().workplace=b.id;v.nutrition=1;v.residents.getFirst().hungerDays=0;s.day(v);assertEquals(22,v.stock.get("CARROT"));}
    @Test void sameModelDoesNotDoubleProductionAcrossChunkModes(){Village a=village(1);a.stock.add("STONE_HOE",1,a.capacity);var b=new Village.Building();b.recipe="garden";b.complete=true;b.resourceConfirmed=true;a.buildings.add(b);a.residents.getFirst().workplace=b.id;Village c=Database.copy(a);Simulation s=new Simulation(rules);s.elapse(a,rules.dayMillis,1);for(int i=0;i<100;i++)s.elapse(c,rules.dayMillis/100,1);assertEquals(a.stock.items,c.stock.items);assertEquals(a.days,c.days);assertEquals(a.residents.getFirst().toolUses,c.residents.getFirst().toolUses);}
    @Test void backlogRemainsAndPausedTimeDoesNotAdvance(){Village v=village(1);Simulation s=new Simulation(rules);s.elapse(v,5*rules.dayMillis,1);assertEquals(1,v.days);assertEquals(4*rules.dayMillis,v.elapsedMillis);v.paused=true;s.elapse(v,3*rules.dayMillis,1);assertEquals(4*rules.dayMillis,v.elapsedMillis);assertEquals(1,v.days);}
    @Test void finiteResourceAndToolsCannotRefreshBySerialization(){Village v=village(1);v.stock.add("STONE_HOE",1,v.capacity);v.stock.add("BREAD",100,v.capacity);var b=new Village.Building();b.complete=true;b.resourceConfirmed=true;b.recipe="garden";b.resourceLeft=1;v.buildings.add(b);v.residents.getFirst().workplace=b.id;Simulation s=new Simulation(rules);s.day(v);v=Database.copy(v);long tools=v.residents.getFirst().toolUses;int carrots=v.stock.get("CARROT");s.day(v);assertEquals(0,v.buildings.getFirst().resourceLeft);assertEquals(tools,v.residents.getFirst().toolUses);assertEquals(carrots-2,v.stock.get("CARROT"));}
    @Test void processingConsumesInputsAndRespectsCapacity(){Village v=village(1);v.stock.add("STONE_PICKAXE",1,v.capacity);v.stock.add("WHEAT",12,v.capacity);var b=new Village.Building();b.recipe="bread";b.complete=true;b.resourceConfirmed=true;v.buildings.add(b);v.residents.getFirst().workplace=b.id;new Simulation(rules).day(v);assertEquals(0,v.stock.get("WHEAT"));assertEquals(3,v.stock.get("BREAD"));}
    @Test void electedReplacementDoesNotResurrectDeadElder(){Village v=village(3);v.residents.getFirst().alive=false;Simulation.electReplacement(v);assertEquals(1,v.residents.stream().filter(r->r.alive && r.role==Village.Role.ELDER).count());assertFalse(v.residents.getFirst().alive);}
    
    @Test void processingBidCapsPreventBreadCraftProfitAtLowestInputAsk(){// Wheat minimum ask: 0.5 each, bread bid cap: 1.2, recipe 3:1.
        assertTrue(rules.prices.get("BREAD").bidCapHundredths()<=3*50);Village v=village(1);v.stock.add("WHEAT",1000,v.capacity);v.stock.add("BREAD",1000,v.capacity);Economy e=new Economy(rules);UUID p=UUID.randomUUID();long input=e.quote(v,p,"WHEAT",24,true).total();v.stock.items.clear();long output=e.quote(v,p,"BREAD",8,false).total();assertTrue(output<=input);
    }
    @Test void contractsReserveBudgetAndPayOnlyDeliveredItems(){Village v=village(5);Economy e=new Economy(rules);UUID p=UUID.randomUUID();long original=v.treasury;var t=Contracts.issue(v,p,"CARROT",4,e);assertEquals(original-t.reward,v.treasury);Contracts.deliver(v,t,2,e);long paid=v.payouts.get(p);assertTrue(paid>0);Contracts.cancel(v,t);assertEquals(original-paid,v.treasury);assertEquals(2,v.stock.get("CARROT"));assertThrows(IllegalArgumentException.class,()->Contracts.deliver(v,t,1,e));}
    @Test void obsoleteRequestAndInsufficientBudgetAreRejected(){Village v=village(5);Economy e=new Economy(rules);v.stock.add("CARROT",1000,v.capacity);assertThrows(IllegalArgumentException.class,()->Contracts.issue(v,UUID.randomUUID(),"CARROT",4,e));v.stock.items.clear();v.treasury=0;assertThrows(IllegalArgumentException.class,()->Contracts.issue(v,UUID.randomUUID(),"CARROT",4,e));}
    @Test void contractsExpireWithoutInventingMoney(){Village v=village(5);Economy e=new Economy(rules);long original=v.treasury;var t=Contracts.issue(v,UUID.randomUUID(),"CARROT",4,e);v.days=t.expiresDay;Contracts.expire(v);assertEquals(original,v.treasury);assertEquals("CANCELLED",t.state);}
    @Test void damagedBuildingCannotProduce(){Village v=village(1);v.stock.add("BREAD",10,v.capacity);var b=new Village.Building();b.complete=true;b.resourceConfirmed=true;b.damaged=true;b.recipe="garden";v.buildings.add(b);v.residents.getFirst().workplace=b.id;new Simulation(rules).day(v);assertEquals(0,v.stock.get("CARROT"));}
    @Test void populationNeedsHousingFoodAndSafety(){Village v=village(5);v.laws.immigration=true;v.stock.add("BREAD",100,v.capacity);Simulation s=new Simulation(rules);v.days=3;s.day(v);assertEquals(5,v.living());var b=new Village.Building();b.complete=true;b.beds=8;v.buildings.add(b);var guard=v.residents.getLast();guard.role=Village.Role.GUARD;v.days=7;s.day(v);assertEquals(6,v.living());v.laws.focus="security";v.days=11;s.day(v);assertEquals(7,v.living());}
}
